///|
async fn git_relay_status(directory : String, status : String) -> Unit {
  @fs.write_file(directory + "/git-status", status, permission=0o600) catch {
    _ => save_diagnostic("git-relay-recording", "degraded")
  }
  save_diagnostic(
    "git-relay",
    status,
    error_type?=if status == "unavailable" {
      Some("readiness_unavailable")
    } else {
      None
    },
  )
}

///|
async fn git_forwarding_enabled(state : Json) -> Bool {
  let options = @json.parse(
    devsy(
      state,
      ["--result-format", "json", "context", "get"],
      "git-relay-options",
    ),
  )
  let option = field(options, "SSH_INJECT_GIT_CREDENTIALS").unwrap_or(
    Json::null(),
  )
  match field(option, "value") {
    Some(Json::String("false")) => false
    Some(Json::String("true")) => true
    _ => field(option, "default") != Some(Json::string("false"))
  }
}

///|
async fn git_relay_ready(state : Json, directory : String) -> Bool {
  // ProxyCommand=false prevents OpenSSH's mux fallback from opening a new
  // Devsy connection and concealing the loss under test.
  let script =
    #|# orca-git-readiness
    #|set -eu
    #|helper=$(git config --global --get credential.helper) || exit 1
    #|case "$helper" in *'internal agent git-credentials'*) ;; *) exit 1 ;; esac
    #|port=12049
    #|previous=
    #|for word in $helper; do
    #|  if test "$previous" = --port; then port=$word; fi
    #|  previous=$word
    #|done
    #|case "$port" in ''|*[!0-9]*) exit 1 ;; esac
    #|test "$port" -ge 1 && test "$port" -le 65535
    #|curl --noproxy '*' -fsS --max-time 2 "http://localhost:$port/" >/dev/null
  let script = script +
    "\ntest \"$(curl --noproxy '*' -fsS --max-time 2 \"http://localhost:$port/owner\")\" = " +
    quote(required(state, "user"))
  @async.with_timeout(4000, async fn() {
    let (code, _, _) = @process.collect_output(
      "ssh",
      ["-o", "ProxyCommand=false", "-o", "ControlMaster=no"] +
      ssh_args(state) +
      ["-S", control_socket(state, directory), script],
    )
    code == 0
  }) catch {
    _ => false
  }
}

///|
async fn stop_git_management(state : Json) -> Unit {
  @async.protect_from_cancel(async fn() {
    @async.with_timeout(2000, async fn() {
      ignore(
        @process.collect_output(
          "ssh",
          ["-o", "ProxyCommand=false"] +
          ssh_args(state) +
          [
            "-S",
            required(state, "socketDirectory") + "/credential-socket",
            "-O",
            "exit",
          ],
        ),
      )
    }) catch {
      _ => ()
    }
    wait_ssh_proxy(state, "management")
    save_diagnostic("git-relay-management", "stopped")
  })
}

///|
async fn monitor_git_relay(
  state : Json,
  directory : String,
  initial_enabled~ : Bool? = None,
) -> Unit {
  let enabled = directory + "/enabled"
  match initial_enabled {
    Some(false) => {
      git_relay_status(directory, "disabled")
      return
    }
    Some(true) => ()
    None =>
      while @fs.exists(enabled) {
        try {
          if !@async.with_timeout(10000, async fn() {
              git_forwarding_enabled(state)
            }) {
            git_relay_status(directory, "disabled")
            return
          }
          break
        } catch {
          _ => {
            git_relay_status(directory, "unavailable")
            save_diagnostic("git-relay-options", "retry", retry_delay_ms=10000)
            @async.sleep(10000)
          }
        }
      }
  }
  let mut last = ""
  let mut attempt = 0
  // A cold primary can take arbitrarily long to start services. Only a relay
  // that was previously ready can be lost; preserve that fact across adoption.
  let established = directory + "/git-established"
  let mut was_ready = @fs.exists(established)
  while @fs.exists(enabled) {
    if git_relay_ready(state, directory) {
      if !was_ready {
        @fs.write_file(established, "", permission=0o600)
        was_ready = true
      }
      if last != "ready" {
        git_relay_status(directory, "ready")
        last = "ready"
      }
      attempt = 0
      @async.sleep(500)
      continue
    }
    if !was_ready {
      if last != "pending" {
        git_relay_status(directory, "pending")
        last = "pending"
      }
      @async.sleep(100)
      continue
    }
    git_relay_status(directory, "unavailable")
    last = "unavailable"
    @async.with_task_group(async fn(group) {
      let sink = @process.redirect_to_file("/dev/null", shared=true)
      defer sink.close()
      let child = @process.spawn(
        group,
        "ssh",
        ssh_args(
          state,
          lease=required(state, "socketDirectory") + "/management-proxy.lock",
        ) +
        [
          "-M",
          "-S",
          required(state, "socketDirectory") + "/credential-socket",
          "-N",
          "-o",
          "ServerAliveInterval=10",
          "-o",
          "ServerAliveCountMax=3",
        ],
        stdin=@process.redirect_from_file("/dev/null"),
        stdout=sink,
        stderr=sink,
        no_wait=true,
      )
      defer child.cancel()
      defer stop_git_management(state)
      save_diagnostic("git-relay-management", "started")
      let deadline = @env.now() + 10000
      let mut recovered = false
      while @fs.exists(enabled) && child.try_wait() is None {
        let ready = git_relay_ready(state, directory)
        if ready && !recovered {
          recovered = true
          attempt = 0
          last = "ready"
          git_relay_status(directory, "ready")
        }
        // 1.23.0 stops the losing service. Recreate only the management
        // connection when the relay vanishes, never the Orca master.
        if (!ready && recovered) || (!recovered && @env.now() >= deadline) {
          break
        }
        @async.sleep(if recovered { 500 } else { 250 })
      }
    }) catch {
      _ => save_diagnostic("git-relay-management", "process-error")
    }
    if @fs.exists(enabled) {
      attempt = if attempt < 5 { attempt + 1 } else { 5 }
      let delay = if attempt < 5 { 250 * (1 << (attempt - 1)) } else { 30000 }
      git_relay_status(directory, "unavailable")
      last = "unavailable"
      save_diagnostic("git-relay", "retry", attempt~, retry_delay_ms=delay)
      @async.sleep(delay)
    }
  }
}
  @fs.mkdir(base, recursive=true, permission=0o700, allow_exist=true)
  let directory = match field(state, "tunnelDirectory") {
    Some(Json::String(old)) if old.has_prefix(base + "/") && @fs.exists(old) =>
      old
    _ => {
      close_tunnel(state)
      let temporary = @fs.tmpdir(prefix="oe")
      let name = temporary.split("/").to_array().last().unwrap().to_owned()
      @fs.rmdir(temporary)
      let directory = base + "/" + name
      @fs.mkdir(directory, permission=0o700)
      set_field(state, "tunnelDirectory", Json::string(directory))
      directory
    }
  }
  let lease = @fs.open(
    directory + "/startup.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer lease.close()
  @async.with_timeout(30000, async fn() {
    while !lease.try_lock(Exclusive) {
      @async.sleep(100)
    }
  })
  if @fs.exists(directory + "/state.json") {
    let saved = @json.parse(@fs.read_file(directory + "/state.json").text())
    guard field(saved, "workspaceUid") == field(state, "workspaceUid") &&
      field(saved, "localPort") ==
      port.map(value => Json::number(value.to_double())) else {
      raise AdapterError("Tunnel ownership changed")
    }
    if worker_alive(directory) {
      wait_tunnel(directory, wait_for_git~)
      return
    }
    // A dead supervisor does not invalidate its still-live SSH transport.
    // Reuse it so Devsy's old service cleanup cannot remove a new owner's helper.
    let reusable = try {
      check_tunnel(saved, directory)
      true
    } catch {
      _ => false
    }
    if reusable {
      for name in ["status.json", "git-status"] {
        if @fs.exists(directory + "/" + name) {
          @fs.remove(directory + "/" + name)
        }
            @fs.read_file(directory + "/state.json").text(),
          )
          validate_state(state)
          if worker_alive(directory) {
            let current = worker_workspace(state, directory)
            guard current is Some(current) &&
              field(current, "uid") == field(state, "workspaceUid") else {
              @fs.remove(directory + "/enabled")
              save_diagnostic("reconnect", "ownership-error")
              return
            }
            if field(current, "running") != Some(Json::boolean(true)) {
              save_diagnostic("reconnect", "workspace-stopped")
              return
            }
          }
          let port = match field(state, "localPort") {
            Some(Json::Number(value, ..)) if value >= 1 &&
              value <= 65535 &&
              value == value.to_int().to_double() => Some(value.to_int())
            None if field(state, "connection") == Some(Json::string("ssh")) =>
              None
            _ => raise AdapterError("Invalid saved tunnel port")
          }
          set_field(state, "tunnelDirectory", Json::string(directory))
          ensure_ssh_worker(state, port)
          save_diagnostic("reconnect", "success")
        } catch {
          AdapterError("Tunnel workspace ownership changed") =>
            save_diagnostic("reconnect", "ownership-error")
          AdapterError("Tunnel workspace stopped") =>
            save_diagnostic("reconnect", "workspace-stopped")
          _ =>
            if @fs.exists(directory) {
              failures += 1
              save_diagnostic("reconnect", "failed")
            } else {
              save_diagnostic("reconnect", "target-removed")
            }
        }
      })
    }
  })
  guard failures == 0 else {
    raise AdapterError(
      "Some tunnels could not be restored; other targets were attempted",
    )
  }
  save_diagnostic("reconnect", "success")
}

///|
async fn workspace_running(state : Json) -> Bool {
  let result = @json.parse(
    @async.with_timeout(10000, async fn() {
      devsy(
        state,
        [
          "--result-format",
          "json",
          "workspace",
          "status",
          required(state, "workspaceId"),
        ],
        "workspace-status",
      )
    }),
  )
  match field(result, "state") {
    Some(Json::String("Running")) => true
    Some(Json::String("Stopped" | "Busy" | "NotFound")) => false
    _ => raise AdapterError("Invalid workspace status")
  }
}

///|
async fn wait_tunnel(directory : String, wait_for_git~ : Bool = true) -> Unit {
  let started = @env.now()
  progress_message("ssh-tunnel: connecting…")
  errdefer progress_message(
    "ssh-tunnel: failed (" + progress_timing(started) + ")",
  )
  @async.with_timeout(30000, async fn() {
    while true {
      if @fs.exists(directory + "/status.json") {
        let status = @json.parse(
          @fs.read_file(directory + "/status.json").text(),
        )
        if field(status, "status") == Some(Json::string("ownership-error")) {
          raise AdapterError("Tunnel workspace ownership changed")
        }
        if field(status, "status") == Some(Json::string("workspace-stopped")) {
          raise AdapterError("Tunnel workspace stopped")
        }
        if field(status, "status") == Some(Json::string("connected")) &&
          worker_alive(directory) {
          let saved = @json.parse(
            @fs.read_file(directory + "/state.json").text(),
          )
          try {
            check_tunnel(saved, directory)
            return
          } catch {
            _ => ()
          }
        }
      }
      @async.sleep(100)
    }
  })
  progress_message("ssh-tunnel: connected (" + progress_timing(started) + ")")
  guard wait_for_git else { return }
  @async.with_timeout(5000, async fn() { wait_git_relay(directory) }) catch {
    _ => ()
  }
  let git_status = if @fs.exists(directory + "/git-status") {
    @fs.read_file(directory + "/git-status").text()
  } else {
    "pending"
  }
  if git_status != "ready" && git_status != "disabled" {
    @stdio.stderr.write(
      "orca-env-devsy: Git credential relay readiness is unavailable; Orca remains connected. Recovery will retry; inspect local git-relay diagnostics.\n",
    ) catch {
      _ => ()
    }
    save_diagnostic("git-relay", "warning", error_type="readiness_unavailable")
  }
}

