func Run(ctx context.Context, opts RunOptions) error {
	if err := opts.validate(); err != nil {
		return err
	}

	sess, err := opts.Client.NewSession()
	if err != nil {
		return fmt.Errorf("failed to create SSH session: %w", err)
	}
	defer func() { _ = sess.Close() }()
	return RunSession(ctx, sess, RunSessionOptions{
		Command: opts.Command,
		Stdin:   opts.Stdin,
		Stdout:  opts.Stdout,
		Stderr:  opts.Stderr,
		EnvVars: opts.EnvVars,
	})
}

// RunSession executes a command on a caller-owned SSH session. It never closes
// the session; callers retain ownership and are responsible for cleanup.
func RunSession(ctx context.Context, sess *ssh.Session, opts RunSessionOptions) error {
	if sess == nil {
		return fmt.Errorf("SSH session is required")
	}
	if opts.Command == "" {
		return fmt.Errorf("command is required")
	}
	// Set environment variables (best effort - SSH servers may reject env vars or not support them)
	for k, v := range opts.EnvVars {
		_ = sess.Setenv(k, v) // Ignore errors - command should work without env vars
	}

	cleanup, err := setupContextCancellation(ctx, sess)
	if err != nil {
		return err
	}
	defer cleanup()

	sess.Stdin = opts.Stdin
	sess.Stdout = opts.Stdout
	sess.Stderr = opts.Stderr

	err = sess.Run(opts.Command)
	if err != nil {
		return handleRunError(ctx, err, opts.Command)
	}

	return nil
}

func setupContextCancellation(ctx context.Context, sess *ssh.Session) (func(), error) {
	if err := ctx.Err(); err != nil {
		return nil, fmt.Errorf("context already cancelled: %w", err)
	}
	done := make(chan struct{})
	go func() {
		select {
		case <-ctx.Done():
			_ = sess.Signal(ssh.SIGINT)
		case <-done:
		}
	}()
	return func() { close(done) }, nil
}

func handleRunError(ctx context.Context, err error, command string) error {
	// If the context was cancelled, EOF and other errors are expected
	// from the session tearing down.
	if ctx.Err() != nil {
		return ctx.Err()
	return &startedSession{session: session, stdin: stdin, stdout: stdout}, nil
}

func (c *sessionConn) Read(p []byte) (int, error)  { return c.stdout.Read(p) }
func (c *sessionConn) Write(p []byte) (int, error) { return c.stdin.Write(p) }

func (c *sessionConn) Close() error {
	var err error
	c.closeOnce.Do(func() {
		c.cancel()
		if closeErr := c.stdin.Close(); closeErr != nil {
			err = closeErr
		}
		if closeErr := c.session.Close(); err == nil && closeErr != nil {
			err = closeErr
		}
	})
	return err
}

func (c *sessionConn) LocalAddr() net.Addr              { return transport.NewAddr("ssh-session") }
func (c *sessionConn) RemoteAddr() net.Addr             { return transport.NewAddr("ssh-session") }
func (c *sessionConn) SetDeadline(time.Time) error      { return os.ErrInvalid }
func (c *sessionConn) SetReadDeadline(time.Time) error  { return os.ErrInvalid }
func (c *sessionConn) SetWriteDeadline(time.Time) error { return os.ErrInvalid }
func (c *sessionConn) Wait() error {
	c.waitOnce.Do(func() {
		c.waitErr = c.session.Wait()
		c.cancel()
		close(c.waitDone)
	})
	<-c.waitDone
	return c.waitErr
}

